pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 _changeFee) public {
        address base = address(0x1);
        address nft = address(0x2);
        uint16 feeRate = 100;
        bytes32 root = bytes32(0);
        c.initialize(base, nft, 100, 100, _changeFee, feeRate, root, false, false);
        uint56 storedFee = c.changeFee();
        assertTrue(storedFee == _changeFee);
    }
}
